import { dataEnoughEnabled } from './dataEnough.mjs'
import { parseInputNumber } from './inputValues.js'
import { calendarDay } from './calendarDate.js'

// ORDRE 284 · commit 1 — "er squatten rent faktisk blevet stærkere siden
// marts": for ÉN øvelse (ikke et hovedløft-bundt), det tungeste gennemførte
// sæt pr. kalenderuge over tid, plus det beregnede énrepetitionsmaksimum.
// Rene funktioner, ingen Supabase/React — samme mønster som volume/beregn.js,
// genbruger dens ugenoegle() (kalenderuge, mandag-søndag, ISO 8601) i stedet
// for at opfinde egen datologik.
//
// estimatedOneRepMax() er UDTRUKKET herfra til AthleteView.jsx's PR-
// detektion og hovedløfts-widget (E1RMChart/fetchWeeklyTonnage) — samme tal
// tre steder er ordrens egen betingelse ("efter samme formel som resten af
// appen bruger"), ikke en ny formel.
//
// The four main-lift series match exact normalized lifts. Picker families can
// organize variants, but estimates for a variant never enter a main-lift series.
// Strength curves use bestEstimatedSetPerWeek; heaviestSetPerWeek remains the
// weight-only summary API for existing consumers.

import { exerciseSetView } from './exerciseSetView.js'
import { erLetSaetNavn } from './exerciseNames.js'
import { ugenoegle } from './volume/ugenoegle.js'

/** Epley: vægt × (1 + reps / 30). Samme formel i hele appen — se filens egen note. */
export function estimatedOneRepMax(weight, reps) {
  const w = parseInputNumber(weight), r = parseInputNumber(reps)
  if (!(w > 0) || !(r > 0)) return 0
  const result = w * (1 + r / 30)
  return Number.isFinite(result) ? result : 0
}

export const HOVEDLOEFT_FAMILIER = [
  { key: 'squat', label: 'Squat', color: '#4e8fcf', match: n => exerciseSetView(n).key === 'squat' },
  { key: 'baenk', label: 'Bænkpres', color: '#c8923a', match: n => exerciseSetView(n).key === 'baenkpres' },
  { key: 'doedloeft', label: 'Dødløft', color: '#6cba6c', match: n => exerciseSetView(n).key === 'doedloeft' },
  { key: 'sumo', label: 'Sumo dødløft', color: '#b68bd1', match: n => exerciseSetView(n).key === 'sumo doedloeft' },
]

/**
 * Hvilken hovedløft-familie et øvelsesnavn hører til: PRÆCIS de fire (Marcs dom
 * 6. okt, V17: "Hovedløft er præcis fire: squat, bænkpres, konventionel
 * dødløft og sumo dødløft. Alt andet (front squat, pause, close-grip, goblet,
 * RDL osv.) er varianter/assistance"). Sættype-suffikser og stavemåder
 * ("Bænkpres top set", "baenk teknik single", "Bench") foldes til samme løft.
 * Varianter giver null og havner under "Andre øvelser".
 */
export function hovedloeftFamilie(navn) {
  return HOVEDLOEFT_FAMILIER.find(f => f.match(navn))?.key ?? null
}

/**
 * Grupperer en liste af ØVELSESNAVNE (typisk alle distinkte navne atleten
 * har logget) til øvelsesvælgeren: de fire hovedløft (ét navn hver) og
 * "andre" (varianter og assistance) — resten,
 * i den rækkefølge de kom ind (kaldestedet sorterer selv om nødvendigt).
 *
 * @param {string[]} navne
 * @returns {{ squat: string[], baenk: string[], doedloeft: string[], sumo: string[], andre: string[] }}
 */
export function grupperOevelsesnavne(navne) {
  const grupper = { squat: [], baenk: [], doedloeft: [], sumo: [], andre: [] }
  for (const navn of navne || []) {
    const familie = hovedloeftFamilie(navn)
    grupper[familie || 'andre'].push(navn)
  }
  return grupper
}

/**
 * Det tungeste gennemførte sæt pr. kalenderuge, for ÉN øvelses logs
 * (kaldestedet filtrerer selv til ét øvelsesnavn). "Tungeste" = højest vægt;
 * ved lige vægt vinder flest reps (mere volumen på samme vægt er stadig
 * fremgang værd at vise).
 *
 * @param {Array<{weight: number, reps_completed: number, logged_at: string}>} logs
 *   Forventes allerede filtreret til skipped:false og weight > 0.
 * @returns {Array<{uge: string, weight: number, reps: number, e1rm: number}>}
 *   ÆLDSTE UGE FØRST (kronologisk, klar til en graf der læses venstre-mod-højre).
 */
export function heaviestSetPerWeek(logs) {
  const bedst = new Map()
  for (const log of logs || []) {
    if (!log || log.skipped) continue
    const weight = parseInputNumber(log.weight), reps = parseInputNumber(log.reps_completed)
    if (!(estimatedOneRepMax(weight, reps) > 0)) continue
    const uge = ugenoegle(log.logged_at)
    if (!uge) continue
    const current = bedst.get(uge)
    if (!current || weight > current.weight || (weight === current.weight && reps > current.reps)) {
      bedst.set(uge, { uge, weight, reps })
    }
  }
  return [...bedst.values()]
    .sort((a, b) => (a.uge < b.uge ? -1 : 1))
    .map(p => ({ ...p, e1rm: Math.round(estimatedOneRepMax(p.weight, p.reps)) }))
}

// Strength estimate uses the best estimate, which can come from a lighter backoff.
export function bestEstimatedSetPerWeek(logs) {
  const best = new Map()
  for (const log of logs || []) {
    if (!log) continue
    const weight = parseInputNumber(log.weight), reps = parseInputNumber(log.reps_completed)
    if (log.skipped || !(weight > 0) || !(reps > 0)) continue
    const uge = ugenoegle(log.logged_at)
    if (!uge) continue
    const val = estimatedOneRepMax(weight, reps)
    if (!(val > 0)) continue
    const cur = best.get(uge)
    if (!cur || val > cur.val || (val === cur.val && weight > cur.weight))
      best.set(uge, { uge, weight, reps, val })
  }
  return [...best.values()].sort((a, b) => a.uge.localeCompare(b.uge))
    .map(({ val, ...p }) => ({ ...p, e1rm: Math.round(val) }))
}

// Ordre 1421: styrke-kurven (Fremgang og forsidens hovedloeft-graf) bygges kun
// af RIGTIGE TUNGE saet. Et saet taeller ikke hvis det er et let saet efter
// navnet (backoff, teknik-single(r), volumen, sekundaer) eller har mere end
// MAX_TUNGE_REPS reps (Epley er upaalidelig langt ude, og det er opvarmning/
// volumen, ikke et styrketal). Saa kan et let saet aldrig traekke kurven ned.
export const MAX_TUNGE_REPS = 8

export function erTungtSaet(navn, reps) {
  const r = parseInputNumber(reps)
  return !erLetSaetNavn(navn) && r > 0 && r <= MAX_TUNGE_REPS
}

// Ordre 1451: en deload-uge er med vilje let og maaler ikke styrke. Et sæt fra en uge hvis
// blokname er deload/aflastning/taper tæller derfor ikke som tungt sæt (samme regel i Fremgang,
// rekorder, forsidens styrkeudvikling, coachens visning og SQL). Blokken kommer fra
// log.exercises.sessions.weeks.block_name; mangler den, er sættet ikke deload.
export const erDeloadBlok = (blokNavn) => /deload|aflast|taper/i.test(String(blokNavn ?? ''))
export const erDeloadLog = (log) => erDeloadBlok(log?.exercises?.sessions?.weeks?.block_name)

const dagNoegle = (iso) => {
  if (dataEnoughEnabled()) return calendarDay(iso)
  if (!calendarDay(iso)) return null
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return null
  const p = n => String(n).padStart(2, '0')
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`
}

/**
 * Hoejeste e1RM pr. DAG, kun fra tunge saet. Logs er raekker med
 * exercises.name (det RAA navn, saa saettypen kan ses), weight, reps_completed,
 * logged_at. Dage uden et tungt saet faar intet punkt (hul, ikke et lavt tal).
 * Aeldste dag foerst.
 */
export function bestHeavySetPerDay(logs) {
  const best = new Map()
  for (const log of logs || []) {
    if (!log) continue
    const weight = parseInputNumber(log.weight), reps = parseInputNumber(log.reps_completed)
    if (log.skipped || !(weight > 0) || erDeloadLog(log) || !erTungtSaet(log.exercises?.name ?? log.navn, reps)) continue
    const dag = dagNoegle(log.logged_at)
    if (!dag) continue
    const val = estimatedOneRepMax(weight, reps)
    if (!(val > 0)) continue
    const cur = best.get(dag)
    if (!cur || val > cur.val || (val === cur.val && weight > cur.weight)) best.set(dag, { dag, weight, reps, val, navn: log.exercises?.name ?? log.navn, ...(dataEnoughEnabled() ? { deload: erDeloadLog(log) } : {}) })
  }
  return [...best.values()].sort((a, b) => a.dag.localeCompare(b.dag))
    .map(({ val, ...p }) => ({ ...p, e1rm: Math.round(val) }))
}

sources.src/exerciseSetView.js:
import { foldNavn, grundnavn } from './exerciseNames.js'

// Read-time lift identity. Original row names and IDs remain unchanged for writes.
const NUM = '(?:\\s*\\d+)?'
const TYPE = '(top(?:[ -]?(?:s(?:æ|ae)t|set))?' + NUM + '|back[ -]?off(?:[ -]?(?:s(?:æ|ae)t|set))?' + NUM +
  '|straight(?:[ -]?(?:s(?:æ|ae)t|sets?))?' + NUM + '|s(?:æ|ae)t\\s*\\d+)'
const suffix = new RegExp(`(?:\\s*[-\u2013:,]\\s*|\\s+)${TYPE}\\s*$`, 'i')
const parentheses = new RegExp(`\\s*\\(${TYPE}\\)\\s*$`, 'i')
const prefix = new RegExp(`^${TYPE}(?:\\s*[-\u2013:,]\\s*|\\s+)(.+)$`, 'i')

const LIFT_ALIASES = {
  squat: 'Squat', 'back squat': 'Squat', 'competition squat': 'Squat', baenk: 'Bænkpres', baenkpres: 'Bænkpres',
  bench: 'Bænkpres', 'bench press': 'Bænkpres',
  doedloeft: 'Dødløft', deadlift: 'Dødløft', dl: 'Dødløft',
  'konventionel doedloeft': 'Dødløft', 'conventional deadlift': 'Dødløft',
  'sumo doedloeft': 'Sumo dødløft', 'sumo deadlift': 'Sumo dødløft',
}

// Programlaegningens egne suffikser ("(comp)", "- volumen") foeles ind via
// grundnavn(); "Doedloeft (sumo)" / "Doedloeft - sumo" er sumo, ikke konventionel.
const SUMO_SUFFIX = /^(d(?:oe|ø)dl(?:oe|ø)ft|deadlift)\s*(?:[-–]\s*sumo|\(\s*sumo\s*\)|sumo)$/i
function foldBase(base) {
  let s = base
  for (let i = 0; i < 4; i++) {
    const g = grundnavn(s).replace(/\s*\((?:comp|competition)\)\s*$/i, '').trim()
    const t = g.replace(suffix, '').replace(parentheses, '').trim()
    const next = t || g
    if (next === s) break
    s = next
  }
  return SUMO_SUFFIX.test(s) ? 'Sumo dødløft' : s
}

export function exerciseSetView(input) {
  const raw = String(input ?? '').trim()
  const leading = raw.match(prefix)
  const match = raw.match(parentheses) || raw.match(suffix) || leading
  const base0 = leading && match === leading ? leading[2].trim() : match ? raw.slice(0, match.index).trim() : raw
  const base = base0 ? foldBase(base0) : base0
  // A bare "Topsaet" is ambiguous; never infer an exercise from its neighbour.
  if (!base) return { name: raw, key: foldNavn(raw), type: 'straight', label: 'Sæt' }
  const token = foldNavn(match?.[1] || '')
  const type = token.startsWith('top') ? 'top' : token.startsWith('back') ? 'backoff' : 'straight'
  const display = base.replace(/ae/gi, m => m[0] === 'A' ? 'Æ' : 'æ')
    .replace(/oe/gi, m => m[0] === 'O' ? 'Ø' : 'ø')
  // Transliteration is deliberately limited to the common lift names below.
  const known = /^(?:baenkpres|doedloeft|sumo doedloeft|konventionel doedloeft)$/i.test(base)
  const alias = LIFT_ALIASES[foldNavn(base)]
  const name = alias || (known ? display : base)
  return { name, key: foldNavn(name), type,
    label: type === 'top' ? 'Top' : type === 'backoff' ? 'Backoff' : 'Sæt' }
}

// Consecutive rows become one visual exercise. A return to a lift after another
// exercise remains in its programmed position (circuits/supersets stay intact).
export function exerciseViewGroups(exercises = []) {
  const groups = []
  for (const ex of exercises || []) {
    const view = exerciseSetView(ex.name)
    let group = groups.at(-1)
    if (!group || !view.key || group.key !== view.key) {
      group = { key: view.key, name: view.name, rows: [], totalSets: 0 }
      groups.push(group)
    }
    const offset = group.totalSets
    group.rows.push({ ex, ...view, offset })
    group.totalSets += Number(ex.sets) || 0
  }
  return groups
}

export function exerciseViewRows(exercises) {
  return exerciseViewGroups(exercises).flatMap(group => group.rows.map((row, i) => ({
    ...row, name: group.name, startsGroup: i === 0, endsGroup: i === group.rows.length - 1,
    totalSets: group.totalSets,
    showPrescription: i === 0 || prescriptionKey(row.ex) !== prescriptionKey(group.rows[i - 1].ex),
  })))
}

// Only collapse identical adjacent prescriptions; differing loads/reps stay visible.
const prescriptionKey = ex => JSON.stringify([ex.sets, ex.reps, ex.intensity,
  ex.recommended_weight ?? null, ex.recommended_weight == null ? ex.name : null])

export function bestExerciseRecords(records = []) {
  const best = new Map()
  for (const r of records) {
    const view = exerciseSetView(r.exercise_name)
    const cur = best.get(view.key)
    const weight = Number(r.weight) || 0, reps = Number(r.reps) || 0
    if (!cur || weight > cur.weight || (weight === cur.weight && reps > cur.reps))
      best.set(view.key, { name: view.name, weight, reps })
  }
  return [...best.values()]
}

export function mainLiftName(name) {
  const view = exerciseSetView(name)
  return ['squat', 'baenkpres', 'doedloeft', 'sumo doedloeft'].includes(view.key) ? view.name : null
}

sources.src/fremgangLogs.js:
// ORDRE 293 · blok 1 (F2) — Fremgang-fanens hentning af al historik. Hentes
// FALDENDE (nyeste først) med grænsen, og vendes bagefter, så en grænse — vores
// egen eller Supabases "Max rows" — altid koster de ÆLDSTE sæt, aldrig de
// nyeste (før: stigende + limit, så kurven endte i fortiden for en atlet med
// mere historik end grænsen). Ingen paginering og ingen datogrænse: hvad
// kurven viser er uændret for alle med færre sæt end grænsen.
export const FREMGANG_LOG_LIMIT = 4000

// ORDRE 456: { fra, til } = én side (range) i stedet for grænsen; se hentAlleSider.
export function fremgangLogsQuery(client, athleteId, { fra = null, til = null } = {}) {
  const q = client
    .from('exercise_logs')
    // ORDRE 439: exercise_id, så ugens egne sæt kan tages fra exerciseLogs
    // i stedet (rekorder.js), uden at et sæt tælles to gange.
    .select('exercise_id, weight, reps_completed, logged_at, exercises(name, sessions(weeks(block_name)))')
    .eq('athlete_id', athleteId)
    .eq('skipped', false)
    .gt('weight', 0)
    .order('logged_at', { ascending: false })
  return fra == null ? q.limit(FREMGANG_LOG_LIMIT) : q.order('id', { ascending: false }).range(fra, til)
}

// Faldende → kronologisk (ældste først), som resten af Fremgang forventer.
export function fremgangLogsKronologisk(rows) {
  return [...(rows || [])].reverse()
}

// ORDRE 450: rækkerne til rekord-indekset (src/athlete/rekordIndeks.js).
// Samme felter og filtre som ovenfor, men kun rækker fra `siden` og frem
// (null = alt, første gang). Faldende med samme grænse, så en grænse også her
// koster de ældste rækker.
export function rekordRaekkerQuery(client, athleteId, siden = null, { fra = null, til = null } = {}) {
  let q = client
    .from('exercise_logs')
    .select('exercise_id, weight, reps_completed, logged_at, exercises(name, sessions(weeks(block_name)))')
    .eq('athlete_id', athleteId)
    .eq('skipped', false)
    .gt('weight', 0)
  if (siden) q = q.gte('logged_at', siden)
  q = q.order('logged_at', { ascending: false })
  return fra == null ? q.limit(FREMGANG_LOG_LIMIT) : q.order('id', { ascending: false }).range(fra, til)
}

// ORDRE 456 (A4 i docs/kritik-446): hele historikken, side for side. Supabase'
// "Max rows" (standard 1000 i et nyt projekt) afskærer stille ethvert svar,
// uanset limit. Med ét kald på 4000 blev "bedst før" regnet ud fra de nyeste
// 1000 eller 4000 sæt, og et almindeligt sæt kunne fejres som rekord, når
// atletens top lå længere tilbage. Nu hentes sider (range, logged_at og id
// faldende, så de ikke overlapper), til en side kommer tom tilbage: så er
// loftet ligegyldigt, hvad prod end står på. lavSide(fra, til) giver et kald
// med { data, error }; svaret har samme form. Flere end MAX_SIDER sider giver
// en fejl, så intet regnes ud fra en halv historik.
export const SIDE_STR = 1000
export const MAX_SIDER = 200

export async function hentAlleSider(lavSide, sideStr = SIDE_STR) {
  const alle = []
  for (let side = 0; side < MAX_SIDER; side++) {
    const { data, error } = await lavSide(alle.length, alle.length + sideStr - 1)
    if (error) return { data: null, error }
    if (!data?.length) return { data: alle, error: null }
    alle.push(...data)
  }
  return { data: null, error: { code: 'FOR_MANGE_SIDER', message: `Historikken er over ${MAX_SIDER * sideStr} rækker` } }
}

sources.src/inputValues.js:
import { parseInputNumber } from './athlete/kostNumbers.mjs'
export { parseInputNumber }
export function inputInteger(value, empty = null) {
  const n = parseInputNumber(value, empty)
  return Number.isSafeInteger(n) ? n : null
}
export function optionalInput(value) {
  return value === null || value === undefined || (typeof value === 'string' && !value.trim())
}
export function finiteProduct(...values) {
  const numbers = values.map(v => parseInputNumber(v))
  if (numbers.some(n => n === null)) return 0
  const result = numbers.reduce((a, b) => a * b, 1)
  return Number.isFinite(result) ? result : 0
}
export function finiteAdd(a, b) {
  return a > Number.MAX_VALUE - b ? Number.MAX_VALUE : a + b
}

export function finiteMean(values) {
  if (!values.length) return null
  const scale = Math.max(...values)
  if (!scale) return 0
  return scale * Math.min(1, values.reduce((sum, value) => sum + (value / scale) / values.length, 0))
}

